"""Intent tests for M1-T19: risk.summary_stats, the annualized whole-period summary (RISK-04)."""

import math

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def returns_from(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={ticker: tuple(values) for ticker, values in payload["values"].items()},
    )


def vol_from(payload: dict) -> VolSeries:
    return VolSeries(
        returns=returns_from(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={ticker: tuple(values) for ticker, values in payload["values"].items()},
    )


def by_ticker(rows: tuple[TickerSummary, ...]) -> dict[str, TickerSummary]:
    return {row.ticker: row for row in rows}


@pytest.mark.intent
def test_tc07_summary_matches_golden(golden):
    inputs, expected = golden("risk", "TC-07")
    tol = expected["tol"]

    result = summary_stats(vol_from(inputs["vol"]))

    assert isinstance(result, tuple)
    assert all(isinstance(row, TickerSummary) for row in result)
    assert [row.ticker for row in result] == [row["ticker"] for row in expected["summary"]]
    actual = by_ticker(result)
    for want in expected["summary"]:
        got = actual[want["ticker"]]
        assert got.ann_return == pytest.approx(want["ann_return"], abs=tol, rel=0)
        assert got.ann_vol == pytest.approx(want["ann_vol"], abs=tol, rel=0)
        assert got.sharpe == pytest.approx(want["sharpe"], abs=tol, rel=0)
        assert got.last_vol == pytest.approx(want["last_vol"], abs=tol, rel=0)


@pytest.mark.intent
def test_tc07_zero_volatility_gives_zero_sharpe(golden):
    inputs, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    want = next(row for row in expected["summary"] if row["ticker"] == "Y")

    got = by_ticker(summary_stats(vol_from(inputs["vol"])))["Y"]

    assert got.ann_vol == pytest.approx(want["ann_vol"], abs=tol, rel=0)
    assert got.sharpe == pytest.approx(want["sharpe"], abs=tol, rel=0)
    assert math.isfinite(got.sharpe)


@pytest.mark.intent
def test_tc07_periods_per_year_scales_return_and_vol(golden):
    inputs, expected = golden("risk", "TC-07")
    tol = expected["tol"]
    want = next(row for row in expected["summary"] if row["ticker"] == "X")
    periods = 365

    got = by_ticker(summary_stats(vol_from(inputs["vol"]), periods))["X"]

    assert got.ann_return == pytest.approx(want["ann_return"] * periods / 252, abs=tol, rel=0)
    assert got.ann_vol == pytest.approx(
        want["ann_vol"] * math.sqrt(periods / 252), abs=tol, rel=0
    )
    assert got.sharpe == pytest.approx(got.ann_return / got.ann_vol, abs=tol, rel=0)


@pytest.mark.intent
def test_fewer_than_two_returns_is_a_value_error(contract_sample):
    payload = contract_sample("risk.VolSeries")
    payload["returns"]["dates"] = payload["returns"]["dates"][:1]
    payload["returns"]["values"] = {
        ticker: values[:1] for ticker, values in payload["returns"]["values"].items()
    }
    payload["values"] = {ticker: [None] for ticker in payload["values"]}

    with pytest.raises(ValueError, match=r"(?i)return|two|2"):
        summary_stats(vol_from(payload))

